  'expectations-are-data.order-unanchoring.event.contracts.label': 'Aparece la indexación en contratos de varios años',
  'expectations-are-data.order-unanchoring.event.regime.label': 'El objetivo deja de ser el supuesto por defecto al fijar precios',
